def preparation_projection(document):
 try:
  from scripts.baseline.r2_followup_attempt_transport_contract import attempt_projection
 except ModuleNotFoundError:
  from r2_followup_attempt_transport_contract import attempt_projection
 result=attempt_projection(document);paths=result['paths'];schemas=result['components']['schemas']
 if not any(k in paths for k in PATHS) and not any(k in schemas for k in SCHEMAS):return result
 for section,pins in ((paths,PATHS),(schemas,SCHEMAS)):
  for key,pin in pins.items():
   if digest(section.pop(key,None))!=pin:raise ValueError('F04 exact preparation contract required: '+key)
